// Tests tab of GET {{baseUrl}}/products/7
pm.test("returns product 7", function () {
  pm.response.to.have.status(200);
});

// Request 1: POST {{baseUrl}}/orders  (Tests tab)
pm.collectionVariables.set("orderId", pm.response.json().id);

// Request 2: GET {{baseUrl}}/orders/{{orderId}}  (Tests tab)
pm.test("order is pending", () => {
  pm.expect(pm.response.json().status).to.eql("pending");
});

const schema = {
  type: "object",
  properties: {
    id:    { type: "integer" },
    price: { type: "number" }
  }
};
pm.test("matches the product schema", () => {
  pm.response.to.have.jsonSchema(schema);
});

// Run in Postman on a laptop, against the staging API in the same office network
pm.test("fast enough", () => {
  pm.expect(pm.response.responseTime).to.be.below(200);
});

// Request 1 (first in the collection): POST {{baseUrl}}/auth/login  - Tests tab
pm.environment.set("token", pm.response.json().access_token);

// Collection-level auth for every other request:
